fn carry_forward(readings: Vec<Option<i64>>, limit: Option<usize>) -> Vec<Option<i64>> {
    let mut filled = Vec::with_capacity(readings.len());
    let mut last: Option<i64> = None; // the most recent real reading, if any
    let mut gap = 0; // consecutive missing readings since it
    for x in readings {
        match x {
            Some(v) => {
                last = Some(v);
                gap = 0;
                filled.push(Some(v));
            }
            None => {
                gap += 1;
                let within = limit.map_or(true, |l| gap <= l);
                filled.push(if within { last } else { None });
            }
        }
    }
    filled
}
